      `${JSON.stringify({
        ts: 1,
        kind: "done",
        channels: [{ channelId: "a", status: "failed", reason: "旧散文" }],
      })}\n`,
    );
    migrateReasonShape();
    const once = read(file);

    migrateReasonShape();

    expect(read(file)).toBe(once);
  });
});

/**
 * dsh-notifier upgrade 域 steps 块 —— 0.2.3 → 0.2.4 的存储布局归位。
 *
 * 判据面：这是唯一**动用户数据**的一步。搬错的表现是静默丢数据——历史读空、状态表回默认、旧文件
 * 留在 home 根目录，而用户只会看到「通知记录没了」。故逐条锁：内容逐字保留、旧文件留痕、
 * 目标已存在时**不覆盖**（用户可能已经在新位置改过东西）、重跑不累积归档。
 */
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";

import {
  HISTORY_FILE_NAME,
  SEQ_FILE_NAME,
  STATUS_FILE_NAME,
  legacyFile,
  notifierFile,
} from "../../../src/server/shared/interface.ts";
import { migrateStorageLayout } from "../../../src/server/upgrade/impl/steps/storage-layout.ts";
import { tempDshHome } from "../../helpers.ts";

/** 本文件内建过的隔离环境，逐个在 afterEach 还原并删除。 */
const cleanups: Array<() => void> = [];

afterEach(() => {
  for (const dispose of cleanups.splice(0)) dispose();
});

/** 建一个隔离 DSH_HOME（迁移的读端与写端都从它解析路径）。 */
function isolatedHome(): string {
  const home = tempDshHome();
  cleanups.push(home.dispose);
  return home.dir;
}

function writeLegacy(name: string, text: string): void {
  writeFileSync(legacyFile(name), text, "utf8");
}

/** 旧文件名 → 新文件名 → 一份有代表性的内容（jsonl 是多行、json 是单行、seq 是数字）。 */
const ENTRIES = [
  ["dsh-notifier-history.jsonl", HISTORY_FILE_NAME, '{"ts":1,"kind":"done"}\n{"ts":2}\n'],
  [
    "dsh-notifier-status.json",
    STATUS_FILE_NAME,
    '{"bark:main":{"lastTs":9,"lastStatus":"ok","failStreak":0}}\n',
  ],
  ["notifier-seq.json", SEQ_FILE_NAME, "7\n"],
] as const;

describe("旧文件归位", () => {
  it.each(ENTRIES)(
    "%s 搬成新布局的 %s：内容逐字保留，旧文件改名留痕",
    (legacyName, targetName, text) => {
      isolatedHome();
      writeLegacy(legacyName, text);

      migrateStorageLayout();

      expect(readFileSync(notifierFile(targetName), "utf8")).toBe(text);
      expect(existsSync(legacyFile(legacyName))).toBe(false);
      expect(readFileSync(`${legacyFile(legacyName)}.migrated.bak`, "utf8")).toBe(text);
    },
  );

  it("没有旧文件时也把初始形态落定（目标不存在会让「这一份处理过了」的判据永远不成立）", () => {
    isolatedHome();
    migrateStorageLayout();

    expect(readFileSync(notifierFile(HISTORY_FILE_NAME), "utf8")).toBe("");
    expect(readFileSync(notifierFile(STATUS_FILE_NAME), "utf8")).toBe("{}\n");
    // 序号文件的初始形态与流侧落盘同形（流侧写 `${seq}\n`）：首次读取要得到 0。
    expect(readFileSync(notifierFile(SEQ_FILE_NAME), "utf8")).toBe("0\n");
  });

  it("目标已存在时只归档旧文件、不覆盖目标（用户可能已经在新位置改过东西，拿历史盖回去就是用旧盖新）", () => {
    const home = isolatedHome();
    mkdirSync(dirname(notifierFile(HISTORY_FILE_NAME)), { recursive: true });
    writeFileSync(notifierFile(HISTORY_FILE_NAME), '{"ts":99}\n', "utf8");
    writeLegacy("dsh-notifier-history.jsonl", '{"ts":1}\n');

    migrateStorageLayout();

    expect(readFileSync(notifierFile(HISTORY_FILE_NAME), "utf8")).toBe('{"ts":99}\n');
    expect(readFileSync(`${legacyFile("dsh-notifier-history.jsonl")}.migrated.bak`, "utf8")).toBe(
      '{"ts":1}\n',
    );
    expect(readdirSync(home)).toContain("dsh-notifier-history.jsonl.migrated.bak");
  });

  it("重跑不累积归档名（旧文件第一次就改成了固定后缀，第二次已无源文件可归档）", () => {
    const home = isolatedHome();
    writeLegacy("dsh-notifier-history.jsonl", '{"ts":1}\n');

    migrateStorageLayout();
    migrateStorageLayout();

    expect(readdirSync(home).filter((name) => name.endsWith(".migrated.bak"))).toEqual([
      "dsh-notifier-history.jsonl.migrated.bak",
    ]);
    expect(readFileSync(notifierFile(HISTORY_FILE_NAME), "utf8")).toBe('{"ts":1}\n');
  });

  it("旧文件读不出来即抛（迁移没做完而启动照常，等于让各域按错误的形态去读数据）", () => {
    isolatedHome();
    // 同名目录：路径存在但没有可读内容——「搬不动」不能被当成「没有旧数据」。
    mkdirSync(legacyFile("dsh-notifier-history.jsonl"), { recursive: true });

    expect(() => migrateStorageLayout()).toThrow(/旧存储文件不可读/u);
  });

  // 归档是「这一份处理过了」的标记：改名失败却继续，旧数据就悬在两套布局之间（新位置有了副本，
  // 归档标记却没有），而用户看到的是「迁移成功」。
  it("旧文件改名失败即抛（归档没成功就不能算这一步做完了）", () => {
    isolatedHome();
    const legacy = legacyFile("dsh-notifier-history.jsonl");
    writeLegacy("dsh-notifier-history.jsonl", '{"ts":1}\n');
    // 归档目标被非空目录占住：rename 覆盖不了它。
    mkdirSync(`${legacy}.migrated.bak`, { recursive: true });
    writeFileSync(join(`${legacy}.migrated.bak`, "占位"), "", "utf8");

    expect(() => migrateStorageLayout()).toThrow(/旧存储文件改名失败/u);
  });
});

/**
 * dsh-notifier upgrade 域 quiet-windows 块 —— 0.2.5 → 0.2.6 免打扰多时间窗割接。
 *
 * 判据面：这是动用户数据的第二步（第一步是 0.2.4 的配置形态割接）。搬错的表现是静默丢时段——
 * 用户配好的深夜窗口在升级后不再生效，而界面只会显示新形态的空列表。故逐条锁：旧起止逐字搬进
 * windows[0]、旧键删除、其余键不动；重跑逐字不动；半截旧形与坏文件不动（不替用户编窗口，
 * 不让一份读不懂的文件阻断启动）。
 */
import { existsSync, readFileSync } from "node:fs";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import {
  CONFIG_FILE_NAME,
  VERSION_FILE_NAME,
  notifierFile,
  writeTextAtomicSync,
} from "../../../src/server/shared/interface.ts";
import type { UpgradeDeps } from "../../../src/server/upgrade/deps.ts";
import { migrateQuietWindows } from "../../../src/server/upgrade/impl/steps/quiet-windows.ts";
import { installUpgrade, releaseUpgrade } from "../../../src/server/upgrade/interface.ts";
import { makeLogger, tempDshHome } from "../../helpers.ts";

let home: { readonly dir: string; dispose: () => void };

beforeEach(() => {
  home = tempDshHome();
});

afterEach(() => {
  releaseUpgrade();
  home.dispose();
});

/** 种一份磁盘上的配置文件。 */
function seedConfig(stored: Record<string, unknown>): void {
  writeTextAtomicSync(notifierFile(CONFIG_FILE_NAME), JSON.stringify(stored, null, 2) + "\n");
}

/** 磁盘上的配置文件内容。 */
function configOnDisk(): Record<string, unknown> {
  return JSON.parse(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")) as Record<
    string,
    unknown
  >;
}

describe("migrateQuietWindows：旧 start/end 搬进 windows[0] 并删旧键", () => {
  it("完整旧形：起止逐字搬进 windows[0]，旧键删除，其余键不动", () => {
    seedConfig({
      notifyAsk: false,
      quietHours: { enabled: true, start: "23:00", end: "07:00", allowKinds: ["error"] },
    });

    migrateQuietWindows();

    const quiet = configOnDisk().quietHours as Record<string, unknown>;
    expect(quiet).toEqual({
      enabled: true,
      windows: [{ start: "23:00", end: "07:00" }],
      allowKinds: ["error"],
    });
    expect(configOnDisk().notifyAsk).toBe(false);
  });

  it("幂等：已迁移的文件重跑逐字不动（压缩格式种文件，缩进会暴露白写一次）", () => {
    const before = JSON.stringify({
      quietHours: { enabled: true, windows: [{ start: "23:00", end: "07:00" }] },
    });
    writeTextAtomicSync(notifierFile(CONFIG_FILE_NAME), before);

    migrateQuietWindows();

    expect(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")).toBe(before);
  });

  it("混合形态（windows 与旧键并存）：清旧键，windows 原样保留", () => {
    seedConfig({
      quietHours: {
        enabled: true,
        start: "23:00",
        end: "07:00",
        windows: [{ start: "12:00", end: "13:00" }],
      },
    });

    migrateQuietWindows();

    const quiet = configOnDisk().quietHours as Record<string, unknown>;
    expect(quiet).toEqual({ enabled: true, windows: [{ start: "12:00", end: "13:00" }] });
  });

  it("半截旧形（缺一半时钟键）：不动，不替用户编半个窗口", () => {
    const before = JSON.stringify({ quietHours: { enabled: true, start: "23:00" } });
    writeTextAtomicSync(notifierFile(CONFIG_FILE_NAME), before);

    migrateQuietWindows();

    expect(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")).toBe(before);
  });

  it("没有 quietHours：文件逐字不动", () => {
    const before = JSON.stringify({ notifyAsk: false });
    writeTextAtomicSync(notifierFile(CONFIG_FILE_NAME), before);

    migrateQuietWindows();

    expect(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")).toBe(before);
  });

  it("没有配置文件：不凭空建一份", () => {
    migrateQuietWindows();

    expect(existsSync(notifierFile(CONFIG_FILE_NAME))).toBe(false);
  });

  it("配置文件不是合法 JSON：不抛，文件不动", () => {
    writeTextAtomicSync(notifierFile(CONFIG_FILE_NAME), "{ 坏掉的\n");
    const before = readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8");

    expect(() => migrateQuietWindows()).not.toThrow();
    expect(readFileSync(notifierFile(CONFIG_FILE_NAME), "utf8")).toBe(before);
  });
});

describe("链级：刻度停在 0.2.5 的装机跑完这一步", () => {
  it("旧形文件被割接，刻度到 0.2.6", () => {
    writeTextAtomicSync(notifierFile(VERSION_FILE_NAME), "0.2.5\n");
    seedConfig({ quietHours: { enabled: true, start: "23:00", end: "07:00" } });
    const face = {
      describe: () => {
        return [] as unknown as ReturnType<UpgradeDeps["legacySettings"]["describe"]>;
      },
    };
    const deps: UpgradeDeps = { logger: makeLogger(), legacySettings: face };

    installUpgrade(deps);

    const quiet = configOnDisk().quietHours as Record<string, unknown>;
    expect(quiet).toEqual({ enabled: true, windows: [{ start: "23:00", end: "07:00" }] });
    expect(readFileSync(notifierFile(VERSION_FILE_NAME), "utf8").trim()).toBe("0.2.6");
  });
});

/**
 * dsh-notifier upgrade 域 version 块 —— 存储刻度与版本比较。
 *
 * 判据面：刻度是「升级做到哪一步」的唯一凭证，读错一处就是整条链空转或永久停摆——而两者的外部表现
 * 与「版本没变」一模一样。版本比较必须**逐段按数值**：字符串比较会把 0.10.0 判成小于 0.9.0，
 * 于是新版本永远升不上去。
 */
import { mkdirSync, readFileSync } from "node:fs";
import { afterEach, describe, expect, it } from "vitest";

import {
  VERSION_FILE_NAME,
  notifierFile,
  writeTextAtomicSync,
} from "../../../src/server/shared/interface.ts";
import {
  compareVersions,
  readStoredVersion,
  writeStoredVersion,
} from "../../../src/server/upgrade/impl/version/index.ts";
import { tempDshHome } from "../../helpers.ts";

/** 本文件内建过的隔离环境，逐个在 afterEach 还原并删除。 */
const cleanups: Array<() => void> = [];

afterEach(() => {
  for (const dispose of cleanups.splice(0)) dispose();
});

/** 建一个隔离 DSH_HOME（刻度的读写都以它为根）。 */
function isolatedHome(): void {
  const home = tempDshHome();
  cleanups.push(home.dispose);
}

/** 构造 Node 文件错误，测试错误码分支而不依赖运行用户的权限位语义。 */
function fileError(code: string): NodeJS.ErrnoException {
  return Object.assign(new Error(`${code}: injected failure`), { code });
}

describe("compareVersions", () => {
  it.each<[string, string, number]>([
    ["0.2.3", "0.2.3", 0],
    ["0.2.4", "0.2.3", 1],
    ["0.2.3", "0.2.4", -1],
    ["0.10.0", "0.9.0", 1],
    ["0.3", "0.3.0", 0],
    // 段数不同时多余的段必须参与比较：只比到较短的那个，`0.2.4 > 0.2` 会被判成相等。
    ["0.2.4", "0.2", 1],
    ["1.0.0", "0.99.99", 1],
  ])("%s 与 %s 比较 → %i", (left, right, expected) => {
    expect(compareVersions(left, right)).toBe(expected);
  });
});

describe("刻度读写", () => {
  it("写进去再读回来是同一个版本号（刻度是纯文本一行，末尾换行不算内容）", () => {
    isolatedHome();
    expect(writeStoredVersion("0.2.4")).toEqual({ ok: true });
    expect(readStoredVersion()).toBe("0.2.4");
    expect(readFileSync(notifierFile(VERSION_FILE_NAME), "utf8")).toBe("0.2.4\n");
  });

  it("没有刻度文件时从 0.0.0 起算：从未升级过的安装要跑整条链（每步自己判断有没有活要干）", () => {
    isolatedHome();
    expect(readStoredVersion()).toBe("0.0.0");
  });

  it.each(["0.2.3\n", "1.4.2\n"])("支持的三段式刻度 %j 保持原值", (text) => {
    isolatedHome();
    writeTextAtomicSync(notifierFile(VERSION_FILE_NAME), text);
    expect(readStoredVersion()).toBe(text.trim());
  });

  it.each(["EACCES", "EIO"])("版本文件读取失败（%s）必须抛出，不能伪装成从未升级", (code) => {
    isolatedHome();
    expect(() =>
      readStoredVersion(() => {
        throw fileError(code);
      }),
    ).toThrow(new RegExp(`存储版本文件读取失败.*${code}`));
  });

  it("版本路径是目录时必须点名 EISDIR，不能从零跑整条链", () => {
    isolatedHome();
    mkdirSync(notifierFile(VERSION_FILE_NAME), { recursive: true });
    expect(() => readStoredVersion()).toThrow(/存储版本文件读取失败.*EISDIR/);
  });

  it("空白刻度文件必须明确报空，不能伪装成从未升级", () => {
    isolatedHome();
    writeTextAtomicSync(notifierFile(VERSION_FILE_NAME), "  \n");
    expect(() => readStoredVersion()).toThrow(/存储版本文件为空/);
  });

  it.each(["not-a-version\n", "0.2.3junk\n", "0.02.3\n", "0.2\n", "2.0.0\n"])(
    "非法或不支持的刻度 %j 必须明确报错",
    (text) => {
      isolatedHome();
      writeTextAtomicSync(notifierFile(VERSION_FILE_NAME), text);
      expect(() => readStoredVersion()).toThrow(/存储版本文件包含非法或不支持的版本号/);
    },
  );
});
